{
  "application": "ppt-generation",
  "case_id": "case-owid-co2-emissions",
  "language": "en",
  "deck": {
    "aspect_ratio": "16:9",
    "slide_count": 9,
    "audience": "policy analysts, climate negotiators, and sustainability researchers reviewing global emission trends",
    "tone": "data-forward, analytical, accessible"
  },
  "brief": {
    "title": "Global CO₂ Emissions: Who Emits, How Much, and What's Changing",
    "one_liner": "A data-driven overview of global CO₂ emission trends by country, region, and per capita — from the Industrial Revolution to 2024.",
    "goal": "Equip the audience with a clear understanding of how global CO₂ emissions are distributed across countries and regions, how shares have shifted historically, and where per capita inequalities persist — informing climate policy and responsibility debates."
  },
  "slides": [
    {
      "id": "title-slide",
      "title": "Global CO₂ Emissions: Who Emits, How Much, and What's Changing",
      "objective": "Cover slide with deck title, subtitle summarizing scope (fossil fuels & industry, 1750–2024), data source attribution (Global Carbon Budget 2025 via Our World in Data), and audience context."
    },
    {
      "id": "global-emissions-growth",
      "title": "Global CO₂ Emissions Grew from 6 Bt in 1950 to Over 35 Bt Today",
      "objective": "Show the trajectory of total global CO₂ emissions from the mid-18th century to 2024 using a line chart or area chart. Highlight the inflection points: slow pre-industrial growth, post-1950 acceleration, and recent slowing but no peak."
    },
    {
      "id": "regional-share-shift",
      "title": "Europe and the US Fell from 90% of Emissions in 1900 to Under One-Third Today",
      "objective": "Visualize the dramatic shift in regional emission shares over time. Use a stacked area or line chart showing how Asia (especially China) rose while Europe and North America declined as a share of global emissions."
    },
    {
      "id": "china-dominates-share",
      "title": "China Now Emits More Than One-Quarter of Global CO₂",
      "objective": "Present a comparison of country-level shares of global CO₂ emissions as of 2024 using a bar chart or treemap. Highlight China (~31%), United States (~13%), India (~8%), and EU-27 (~6%)."
    },
    {
      "id": "per-capita-inequality",
      "title": "Per Capita Emissions Range from 0.1 t in Chad to ~14 t in the US and Canada",
      "objective": "Use a world map or horizontal bar chart to show per capita CO₂ emissions. Emphasize the 150x gap between the poorest Sub-Saharan African nations and the US/Australia/Canada (~14–15 t/person). Note that European countries like France and the UK are much lower than the US despite similar living standards."
    },
    {
      "id": "per-capita-trends-over-time",
      "title": "Per Capita Emissions Vary Widely: ~14 t in the US vs. ~9 t in China and ~2 t in India",
      "objective": "Present a snapshot comparison of current per capita CO₂ emissions for key countries (US ~14 t, Canada ~14 t, China ~9 t, South Africa ~7 t, EU-27 ~6 t, World average ~4.5 t, UK ~4 t, India ~2 t, Kenya ~0.4 t) using a horizontal bar chart. Highlight that China's per capita emissions remain below the US despite being the largest total emitter, and that India remains very low at ~2 t. Reference figure_8.jpg for additional context on how these figures have evolved over time."
    },
    {
      "id": "annual-change-2024",
      "title": "2024 Snapshot: Many Western Nations Cut Emissions While Parts of Asia and Africa Grew",
      "objective": "Display the 2024 annual percentage change in CO₂ emissions using a choropleth map or diverging bar chart. Show that the US, EU, and UK saw declines (blue shading) while Russia, parts of Southeast Asia, and some African nations saw increases (red/orange shading)."
    },
    {
      "id": "energy-mix-matters",
      "title": "Energy Mix Explains Why France and the UK Emit Far Less Per Capita Than Germany or the US",
      "objective": "Illustrate the qualitative insight from the source data: among wealthy nations with similar prosperity levels, per capita emissions vary significantly because of energy mix choices. France, the UK, and Portugal have much lower per capita emissions than Germany, the Netherlands, or the US, largely because a higher share of their electricity comes from nuclear and renewable sources rather than fossil fuels. Use available per capita figures (US ~14 t, UK ~4 t, EU-27 ~6 t) alongside the qualitative explanation as a text-and-chart slide rather than a detailed energy breakdown."
    },
    {
      "id": "key-takeaways",
      "title": "Key Takeaways: Responsibility Is Shared but Unequal",
      "objective": "Summary slide with 4–5 bullet points: (1) Global emissions exceed 35 Bt/yr and haven't peaked; (2) China is the largest annual emitter but per capita still below the US; (3) Historical responsibility is dominated by Europe and the US; (4) Per capita gaps of 150x persist between richest and poorest nations; (5) Energy policy and technology choices can decouple prosperity from emissions."
    }
  ]
}

