            gap: clamp(0.3rem, 0.6vh, 0.5rem);
            width: 100%;
        }

        .diverging-bar-chart .bar-row {
            display: grid;
            grid-template-columns: 100px 8px 1fr 50px;
            align-items: center;
            gap: clamp(0.4rem, 0.8vw, 0.75rem);
        }

        .diverging-bar-chart .bar-label {
            font-family: var(--font-ui);
            font-size: clamp(0.6rem, 0.9vw, 0.78rem);
            color: var(--text-secondary);
            text-align: right;
        }

        .diverging-bar-chart .bar-center {
            width: 2px;
            height: 100%;
            background: var(--text-muted);
            opacity: 0.4;
        }

        .diverging-bar-chart .bar-track {
            height: clamp(10px, 1.6vh, 14px);
            background: var(--bg-elevated);
            border-radius: 2px;
            overflow: hidden;
            position: relative;
        }

        .diverging-bar-chart .bar-fill {
            position: absolute;
            height: 100%;
            border-radius: 2px;
            transition: width 1s var(--ease-out-expo);
        }

        .diverging-bar-chart .bar-fill.negative {
            right: 50%;
            background: var(--color-blue);
        }

        .diverging-bar-chart .bar-fill.positive {
            left: 50%;
            background: var(--color-red);
        }

        .diverging-bar-chart .bar-value {
            font-family: var(--font-ui);
            font-size: clamp(0.6rem, 0.9vw, 0.78rem);
            color: var(--text-primary);
            font-weight: 600;
            font-variant-numeric: tabular-nums;
        }

        .diverging-bar-chart .bar-value.negative { color: var(--color-blue); }
        .diverging-bar-chart .bar-value.positive { color: var(--color-red); }

        /* ===========================================
           KEY INSIGHT BOX
           =========================================== */
        .key-insight {
            background: linear-gradient(135deg, rgba(212, 168, 67, 0.1) 0%, rgba(61, 157, 143, 0.05) 100%);
            border: 1px solid rgba(212, 168, 67, 0.2);
            border-radius: 4px;
            padding: clamp(0.75rem, 1.5vw, 1.25rem);
            margin-top: var(--content-gap);
        }

        .key-insight p {
            font-family: var(--font-ui);
            font-size: clamp(0.7rem, 1.1vw, 0.9rem);
            color: var(--text-secondary);
            line-height: 1.5;
        }

        .key-insight strong {
            color: var(--accent);
        }

        /* ===========================================
           RESPONSIVE
           =========================================== */
        @media (max-width: 768px) {
            .two-col, .three-col {
                grid-template-columns: 1fr;
            }
        }

        @media (prefers-reduced-motion: reduce) {
            *, *::before, *::after {
                animation-duration: 0.01ms !important;
                transition-duration: 0.2s !important;
            }
            html { scroll-behavior: auto; }
        }
    </style>
</head>
