    <script>
        /* ===========================================
           SLIDE PRESENTATION CONTROLLER
           =========================================== */
        class SlidePresentation {
            constructor() {
                this.slides = document.querySelectorAll('.slide');
                this.currentSlide = 0;
                this.setupIntersectionObserver();
                this.setupKeyboardNav();
                this.setupProgressBar();
                this.setupNavDots();
            }

            setupIntersectionObserver() {
                const options = {
                    root: null,
                    threshold: 0.5
                };

                const observer = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('visible');
                            const slideIndex = Array.from(this.slides).indexOf(entry.target);
                            this.currentSlide = slideIndex;
                            this.updateProgress();
                            this.updateNavDots();
                        }
                    });
                }, options);

                this.slides.forEach(slide => observer.observe(slide));
            }

            setupKeyboardNav() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown' || e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') {
                        e.preventDefault();
                        this.nextSlide();
                    } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft' || e.key === 'PageUp') {
                        e.preventDefault();
                        this.prevSlide();
                    }
                });
            }

            nextSlide() {
                if (this.currentSlide < this.slides.length - 1) {
                    this.currentSlide++;
                    this.slides[this.currentSlide].scrollIntoView({ behavior: 'smooth' });
                }
            }

            prevSlide() {
                if (this.currentSlide > 0) {
                    this.currentSlide--;
                    this.slides[this.currentSlide].scrollIntoView({ behavior: 'smooth' });
                }
            }

            setupProgressBar() {
                this.progressBar = document.getElementById('progressBar');
            }

            updateProgress() {
                const progress = ((this.currentSlide + 1) / this.slides.length) * 100;
                this.progressBar.style.width = progress + '%';
            }

            setupNavDots() {
                const navDots = document.getElementById('navDots');
                this.slides.forEach((slide, index) => {
                    const dot = document.createElement('div');
                    dot.className = 'nav-dot' + (index === 0 ? ' active' : '');
                    dot.addEventListener('click', () => {
                        slide.scrollIntoView({ behavior: 'smooth' });
                    });
                    navDots.appendChild(dot);
                });
                this.navDots = navDots.querySelectorAll('.nav-dot');
            }

            updateNavDots() {
                this.navDots.forEach((dot, index) => {
                    dot.classList.toggle('active', index === this.currentSlide);
                });
            }
        }

        document.addEventListener('DOMContentLoaded', () => {
            new SlidePresentation();
            // Trigger first slide as visible
            document.querySelector('.slide').classList.add('visible');
        });
    </script>
